/*
 * Lucky wheel remote spin: WebSocket relay on port 443 (Cloudflare Worker).
 *
 * Mobile carriers block uncommon ports, so a phone on 4G/5G cannot reach the public brokers' WebSocket ports
 * (8884, 8084). The page connects here over wss:// on 443 instead, and this Worker pipes the bytes of the MQTT
 * connection, unchanged, to the broker's plain TCP port 1883, where the boards are. Every message is already
 * end-to-end encrypted with the key from the link, so the relay sees only ciphertext, like the brokers.
 *
 *   wss://<worker>/hivemq -> broker.hivemq.com:1883
 *   wss://<worker>/emqx   -> broker.emqx.io:1883
 *
 * Only pages from ALLOWED_ORIGINS (comma separated, set in wrangler.toml) may use it.
 */
import { connect } from 'cloudflare:sockets';

const BROKERS = { hivemq: 'broker.hivemq.com', emqx: 'broker.emqx.io' };

export default {
	async fetch(request, env) {
		const url = new URL(request.url);
		const host = BROKERS[url.pathname.replace(/^\/+|\/+$/g, '')];
		if (request.headers.get('Upgrade') !== 'websocket') {
			return new Response('Lucky wheel relay. Use wss://' + url.host + '/hivemq or /emqx.\n', { status: host ? 426 : 200 });
		}
		if (!host) return new Response('Unknown broker\n', { status: 404 });
		const allowed = String(env.ALLOWED_ORIGINS || '').split(',').map((s) => s.trim()).filter(Boolean);
		const origin = request.headers.get('Origin') || '';
		if (!allowed.includes(origin)) return new Response('Origin not allowed\n', { status: 403 });

		let socket;
		try { socket = connect({ hostname: host, port: 1883 }); } catch (e) { return new Response('Broker unreachable\n', { status: 502 }); }
		const [client, server] = Object.values(new WebSocketPair());
		server.accept();
		const writer = socket.writable.getWriter();
		let closed = false;
		const closeAll = (code, why) => {
			if (closed) return;
			closed = true;
			try { server.close(code, why); } catch (e) {}
			try { socket.close(); } catch (e) {}
		};
		server.addEventListener('message', (e) => {
			const data = typeof e.data === 'string' ? new TextEncoder().encode(e.data) : new Uint8Array(e.data);
			writer.write(data).catch(() => closeAll(1011, 'broker write failed'));
		});
		server.addEventListener('close', () => closeAll(1000, ''));
		server.addEventListener('error', () => closeAll(1011, 'client error'));
		(async () => {
			const reader = socket.readable.getReader();
			try {
				for (;;) {
					const { value, done } = await reader.read();
					if (done) break;
					server.send(value);
				}
				closeAll(1000, 'broker closed');
			} catch (e) {
				closeAll(1011, 'broker read failed');
			}
		})();
		const wanted = (request.headers.get('Sec-WebSocket-Protocol') || '').split(',').map((s) => s.trim());
		const headers = wanted.includes('mqtt') ? { 'Sec-WebSocket-Protocol': 'mqtt' } : {};
		return new Response(null, { status: 101, webSocket: client, headers });
	}
};
